drop function if exists setup_vector_store;
create function setup_vector_store(table_name text)
returns void
begin
  prepare s from format(' create table %1$I (id bigint primary key generated always as identity, description text, metadata jsonb); drop function if exists match_strategies(int, jsonb); create function match_strategies (match_count int default null, filter jsonb default ''{}''::jsonb) returns table (id bigint, description text, metadata jsonb, similarity float) language plpgsql as $f2$ begin return query select id, description, metadata, 1 as similarity from %1$I where metadata @> filter limit match_count; end; $f2$; ', table_name);
  execute s;
  deallocate prepare s;
end;

