drop function if exists GapFillInternal;
create function GapFillInternal(
  s anyelement,
  v anyelement
)
returns anyelement
begin
  if (
    s is null
    and v is null
  ) then
    return null;
  elseif v is null then
    return s;
  else
    return v;
  end if;
end;

set @t = @@group_concat_max_len;
set @@group_concat_max_len = 4294967295;
select
  rs.raceId as race_id,
  (
    select group_concat(cast(constructorId as char) order by res.resultId separator ',')
    from results as res
    where res.raceId = rs.raceId
  ) as constructor_ids,
  (
    select group_concat(cast(p.stop as char) order by p.raceId separator ', ')
    from pitstops as p
    where rs.raceId = p.raceId
  ) as stops
from races as rs;
set @@group_concat_max_len = @t;

set @t = @@group_concat_max_len;
set @@group_concat_max_len = 4294967295;
select json_objectagg(label, groupedMolecules) as molecules_by_label
from (
  select
    label,
    json_merge_preserve(
      '[]',
      concat(
        '[',
        group_concat(json_object(
          'molecule_id', molecule.molecule_id,
          'atoms', (
            select json_merge_preserve(
              '[]',
              concat(
                '[',
                group_concat(json_object(
                  'atom_id', atom.atom_id,
                  'element', atom.element
                ) separator ','),
                ']'
              )
            )
            from atom
            where atom.molecule_id = molecule.molecule_id
          ),
          'bonds', (
            select json_merge_preserve(
              '[]',
              concat(
                '[',
                group_concat(json_object(
                  'bond_id', bond.bond_id,
                  'bond_type', bond.bond_type
                ) separator ','),
                ']'
              )
            )
            from bond
            where bond.molecule_id = molecule.molecule_id
          )
        ) separator ','),
        ']'
      )
    ) as groupedMolecules
  from molecule
  group by label
) as sub;
set @@group_concat_max_len = @t;
